// Custom Worker entry: the OpenNext-generated app worker plus a daily cron
// trigger. wrangler.jsonc points "main" here. The cron handler calls the app's
// own /api/cron/* routes through the WORKER_SELF_REFERENCE service binding, so
// every job runs as its own invocation with its own limits.
// @ts-ignore - generated by `opennextjs-cloudflare build`
import handler from './.open-next/worker.js';
// @ts-ignore
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
import { cronToken } from './src/lib/cron-auth';

const ORIGIN = 'https://app.ignitesafety.shop';
const JOBS: { path: string; method: string; repeat: boolean }[] = [
  { path: '/api/cron/recurring', method: 'POST', repeat: true },
  { path: '/api/cron/reminders', method: 'POST', repeat: true },
  { path: '/api/cron/service-due', method: 'POST', repeat: true },
  { path: '/api/admin/exchange-rates/refresh', method: 'POST', repeat: false },
];

async function runJobs(env: any) {
  const token = await cronToken(env.NEXTAUTH_SECRET);
  for (const job of JOBS) {
    for (let i = 0; i < (job.repeat ? 6 : 1); i++) {
      try {
        const res: Response = await env.WORKER_SELF_REFERENCE.fetch(
          new Request(`${ORIGIN}${job.path}`, { method: job.method, headers: { 'x-cron-token': token } })
        );
        const body: any = await res.json().catch(() => ({}));
        console.log(`[cron] ${job.path} -> ${res.status} ${body.summary ?? ''}`);
        if (!body.more) break;
      } catch (e: any) {
        console.log(`[cron] ${job.path} failed: ${e?.message ?? e}`);
        break;
      }
    }
  }
}

export default {
  fetch: (handler as any).fetch,
  async scheduled(_controller: any, env: any, ctx: any) {
    ctx.waitUntil(runJobs(env));
  },
};
